using System.Collections.Generic;
using UnityEngine;

namespace RoadGame
{
    /// <summary>
    /// Game audio: one-shot banks (several recorded-style variations each, from Resources/Audio, generated by
    /// Tools/AudioGen/gen_audio.py), material-aware impacts / breakage, ambience and tire loops, two-layer adaptive
    /// music and the real-time engine (EngineAudio on the car).
    /// </summary>
    public class Sfx : MonoBehaviour
    {
        public enum Kind
        {
            Hit, Crit, Smash, Explode, Harpoon, Hook, Absorb, Hurt, Shoot, Warn, LevelUp, Click, Break, Unlock,
            Cannon, Casing, Reel, Crash, ExplodeBig, Rumble, Gem, Repair, Glass, Ignition, Gate, Chest, Open,
            EnemyGun, Throw
        }

        enum Mat { Metal, Wood, Rock, Flesh, Soft }

        class Bank
        {
            public AudioClip[] clips;
            public float volume = 1f;
            public float minInterval = 0.03f;
            public int maxVoices = 4;
            public float pitchVar = 0.04f;
            public int priority = 128;
            public int last = -1;
            public float lastTime = -10f;
        }

        class Voice
        {
            public AudioSource src;
            public Bank bank;
            public float endTime;
            public int priority;
        }

        bool _on = true;
        public bool on
        {
            get => _on;
            set { _on = value; if (!value) StopAllVoices(); }
        }
        bool _musicOn = true;
        public bool musicOn
        {
            get => _musicOn;
            set { _musicOn = value; }
        }

        readonly Dictionary<string, Bank> banks = new Dictionary<string, Bank>();
        Bank[] kindBanks;
        readonly Voice[] voices = new Voice[26];
        AudioSource wind, rolling, skidAsphalt, skidDirt;
        AudioSource musicBase, musicAction;
        float musicIntensity, duckUntil, duck = 1f;
        float absorbCombo; int absorbStep;
        public EngineAudio engine;
        bool loaded;

        public static Sfx Create()
        {
            var go = new GameObject("Sfx");
            var s = go.AddComponent<Sfx>();
            s.Build();
            return s;
        }

        // ------------------------------------------------------------------ setup
        void Build()
        {
            var all = Resources.LoadAll<AudioClip>("Audio");
            var groups = new Dictionary<string, List<AudioClip>>();
            AudioClip windClip = null, rollClip = null, skidA = null, skidD = null, mBase = null, mAction = null;
            foreach (var c in all)
            {
                var n = c.name;
                if (n == "loop_wind") { windClip = c; continue; }
                if (n == "loop_rolling") { rollClip = c; continue; }
                if (n == "loop_skid_asphalt") { skidA = c; continue; }
                if (n == "loop_skid_dirt") { skidD = c; continue; }
                if (n == "music_theme") { mBase = c; continue; }   // Scarbound loop from Tools/MusicGen (no combat layer)
                if (n == "music_action") { mAction = c; continue; }
                if (!n.StartsWith("sfx_")) continue;
                int us = n.LastIndexOf('_');
                var key = n.Substring(4, us - 4);         // sfx_impact_metal_3 -> impact_metal
                if (!groups.TryGetValue(key, out var list)) { list = new List<AudioClip>(); groups[key] = list; }
                list.Add(c);
            }
            foreach (var kv in groups)
            {
                kv.Value.Sort((a, b) => string.CompareOrdinal(a.name, b.name));
                banks[kv.Key] = new Bank { clips = kv.Value.ToArray() };
            }
            loaded = banks.Count > 0;
            if (!loaded) Debug.LogWarning("RoadGame: no audio clips found in Resources/Audio");

            // per-bank mix (volumes are relative to the generator's loudness normalization)
            Tune("cannon", 0.62f, 0.05f, 3, 0.05f, 200);
            Tune("casing", 0.32f, 0.06f, 3, 0.06f, 20);
            foreach (var m in new[] { "metal", "wood", "rock", "flesh", "soft" }) Tune("impact_" + m, 0.5f, 0.04f, 4, 0.06f, 120);
            Tune("crit", 0.55f, 0.06f, 2, 0.04f, 150);
            foreach (var m in new[] { "wood", "metal", "rock", "body", "soft" }) Tune("break_" + m, 0.62f, 0.05f, 3, 0.05f, 160);
            Tune("explode", 0.75f, 0.08f, 3, 0.06f, 220);
            Tune("explodebig", 0.9f, 0.2f, 2, 0.04f, 250);
            Tune("smash", 0.7f, 0.06f, 2, 0.05f, 180);
            Tune("harpoon", 0.45f, 0.05f, 3, 0.05f, 110);
            Tune("hook", 0.4f, 0.05f, 3, 0.05f, 100);
            Tune("reel", 0.3f, 0.06f, 3, 0.05f, 60);
            Tune("absorb", 0.5f, 0.03f, 4, 0f, 140);
            Tune("hurt", 0.6f, 0.08f, 2, 0.05f, 210);
            Tune("crash", 0.62f, 0.12f, 2, 0.05f, 200);
            Tune("shoot", 0.45f, 0.06f, 3, 0.05f, 100);
            Tune("warn", 0.7f, 0.4f, 1, 0f, 240);
            Tune("rumble", 0.7f, 0.4f, 1, 0f, 230);
            Tune("levelup", 0.62f, 0.2f, 1, 0f, 255);
            Tune("unlock", 0.75f, 0.3f, 1, 0f, 255);
            Tune("click", 0.5f, 0.03f, 2, 0.03f, 255);
            Tune("open", 0.35f, 0.05f, 1, 0.04f, 200);
            Tune("gem", 0.55f, 0.1f, 2, 0.02f, 220);
            Tune("repair", 0.32f, 0.12f, 2, 0.06f, 50);
            Tune("glass", 0.5f, 0.2f, 1, 0.04f, 200);
            Tune("ignition", 0.55f, 0.5f, 1, 0.03f, 220);
            Tune("gate", 0.7f, 0.5f, 1, 0f, 230);
            Tune("chest", 0.6f, 0.2f, 1, 0f, 220);
            Tune("enemygun", 0.42f, 0.05f, 4, 0.06f, 130);
            Tune("throw", 0.45f, 0.06f, 3, 0.06f, 100);

            kindBanks = new Bank[System.Enum.GetValues(typeof(Kind)).Length];
            void K(Kind k, string b) { banks.TryGetValue(b, out var bank); kindBanks[(int)k] = bank; }
            K(Kind.Hit, "impact_metal"); K(Kind.Crit, "crit"); K(Kind.Smash, "smash"); K(Kind.Explode, "explode");
            K(Kind.Harpoon, "harpoon"); K(Kind.Hook, "hook"); K(Kind.Absorb, "absorb"); K(Kind.Hurt, "hurt");
            K(Kind.Shoot, "shoot"); K(Kind.Warn, "warn"); K(Kind.LevelUp, "levelup"); K(Kind.Click, "click");
            K(Kind.Break, "break_wood"); K(Kind.Unlock, "unlock"); K(Kind.Cannon, "cannon"); K(Kind.Casing, "casing");
            K(Kind.Reel, "reel"); K(Kind.Crash, "crash"); K(Kind.ExplodeBig, "explodebig"); K(Kind.Rumble, "rumble");
            K(Kind.Gem, "gem"); K(Kind.Repair, "repair"); K(Kind.Glass, "glass"); K(Kind.Ignition, "ignition");
            K(Kind.Gate, "gate"); K(Kind.Chest, "chest"); K(Kind.Open, "open");
            K(Kind.EnemyGun, "enemygun"); K(Kind.Throw, "throw");

            for (int i = 0; i < voices.Length; i++)
            {
                var a = gameObject.AddComponent<AudioSource>();
                a.playOnAwake = false;
                a.spatialBlend = 0f;
                a.dopplerLevel = 0f;
                voices[i] = new Voice { src = a };
            }
            wind = MakeLoop(windClip, 0f);
            rolling = MakeLoop(rollClip, 0f);
            skidAsphalt = MakeLoop(skidA, 0f);
            skidDirt = MakeLoop(skidD, 0f);
            musicBase = MakeLoop(mBase, 0f, false);
            musicAction = MakeLoop(mAction, 0f, false);
            if (musicBase != null && musicAction != null)
            {
                double t0 = AudioSettings.dspTime + 0.3;
                musicBase.PlayScheduled(t0);
                musicAction.PlayScheduled(t0);
            }
            else
            {
                if (musicBase != null) musicBase.Play();
                if (musicAction != null) musicAction.Play();
            }
        }

        void Tune(string bank, float vol, float minInterval, int maxVoices, float pitchVar, int priority)
        {
            if (!banks.TryGetValue(bank, out var b)) return;
            b.volume = vol; b.minInterval = minInterval; b.maxVoices = maxVoices; b.pitchVar = pitchVar; b.priority = priority;
        }

        AudioSource MakeLoop(AudioClip clip, float vol, bool play = true)
        {
            if (clip == null) return null;
            var a = gameObject.AddComponent<AudioSource>();
            a.clip = clip;
            a.loop = true;
            a.playOnAwake = false;
            a.spatialBlend = 0f;
            a.volume = vol;
            a.priority = 40;
            if (play) a.Play();
            return a;
        }

        void StopAllVoices()
        {
            foreach (var v in voices) if (v != null && v.src != null) v.src.Stop();
        }

        // ------------------------------------------------------------------ playback
        public void Play(Kind k, Vector3 pos, float vol = 1f, float pitch = 1f)
        {
            if (kindBanks == null) return;
            PlayBank(kindBanks[(int)k], pos, vol, pitch);
        }

        AudioSource PlayBank(Bank b, Vector3 pos, float vol, float pitch, int variant = -1)
        {
            if (!_on || b == null || b.clips.Length == 0) return null;
            float now = Time.unscaledTime;
            if (now - b.lastTime < b.minInterval) return null;
            // concurrency limit per bank
            int playing = 0;
            foreach (var v in voices) if (v.bank == b && v.endTime > now) playing++;
            if (playing >= b.maxVoices) return null;
            // spatial: pan by screen x, fade with distance from the car (pos == zero -> UI / 2D)
            float pan = 0f, att = 1f;
            if (pos != Vector3.zero && Game.I != null && Game.I.cam != null && Game.I.player != null)
            {
                var vp = Game.I.cam.WorldToViewportPoint(pos);
                pan = Mathf.Clamp((vp.x - 0.5f) * 1.3f, -0.75f, 0.75f);
                var d = pos - Game.I.player.Pos; d.y = 0;
                att = Mathf.Clamp01(1f - (d.magnitude - 14f) / 32f);
                if (att <= 0.02f) return null;
            }
            // pick a variation, never the same twice in a row
            int idx = variant >= 0 ? Mathf.Min(variant, b.clips.Length - 1) : Random.Range(0, b.clips.Length);
            if (variant < 0 && b.clips.Length > 1 && idx == b.last) idx = (idx + 1 + Random.Range(0, b.clips.Length - 1)) % b.clips.Length;
            b.last = idx;
            b.lastTime = now;
            var voice = GetVoice(b.priority, now);
            if (voice == null) return null;
            var clip = b.clips[idx];
            var s = voice.src;
            s.clip = clip;
            s.volume = Mathf.Clamp01(vol * b.volume * att);
            s.pitch = pitch * (1f + Random.Range(-b.pitchVar, b.pitchVar));
            s.panStereo = pan;
            s.Play();
            voice.bank = b;
            voice.priority = b.priority;
            voice.endTime = now + clip.length / Mathf.Max(0.1f, s.pitch);
            return s;
        }

        Voice GetVoice(int priority, float now)
        {
            Voice best = null;
            float bestScore = float.MaxValue;
            foreach (var v in voices)
            {
                if (v.endTime <= now || !v.src.isPlaying) return v;
                // steal: lowest priority first, then the one closest to its end
                float score = v.priority * 10f + (v.endTime - now);
                if (score < bestScore) { bestScore = score; best = v; }
            }
            if (best != null && best.priority <= priority) return best;
            return null;
        }

        static Mat MaterialOf(ModelId id)
        {
            switch (id)
            {
                case ModelId.Crates: case ModelId.Shack: case ModelId.Tower: case ModelId.DeadTree: case ModelId.Hut: case ModelId.SwampTree: case ModelId.Chest:
                    return Mat.Wood;
                case ModelId.Boulder: case ModelId.RedRock: case ModelId.SaltRock: case ModelId.ToxicRock: case ModelId.SaltCrystal: case ModelId.Skull: case ModelId.RibCage:
                    return Mat.Rock;
                case ModelId.Scav: case ModelId.Raider: case ModelId.Spearman: case ModelId.Crossbow: case ModelId.Brute: case ModelId.BossBaron:
                    return Mat.Flesh;
                case ModelId.BossColossus:
                    return Mat.Rock;
                case ModelId.Cactus: case ModelId.Tires: case ModelId.Tent: case ModelId.DryBush: case ModelId.Mushroom:
                    return Mat.Soft;
                default:
                    return Mat.Metal;
            }
        }

        /// <summary>Shell / weapon impact on a target: material-specific hit (+ crit accent).</summary>
        public void Impact(Target t, Vector3 point, bool crit, float vol = 1f)
        {
            if (t == null || t.spec == null) return;
            var m = MaterialOf(t.spec.model);
            string bank = m == Mat.Metal ? "impact_metal" : m == Mat.Wood ? "impact_wood" : m == Mat.Rock ? "impact_rock" : m == Mat.Flesh ? "impact_flesh" : "impact_soft";
            banks.TryGetValue(bank, out var b);
            PlayBank(b, point, vol, t.IsBoss ? 0.85f : 1f);
            if (crit) Play(Kind.Crit, point, 0.9f);
        }

        /// <summary>Destruction sound by material (vehicles / fuel use explosions instead).</summary>
        public void Break(Target t)
        {
            if (t == null || t.spec == null) return;
            var m = MaterialOf(t.spec.model);
            string bank = m == Mat.Metal ? "break_metal" : m == Mat.Wood ? "break_wood" : m == Mat.Rock ? "break_rock" : m == Mat.Flesh ? "break_body" : "break_soft";
            banks.TryGetValue(bank, out var b);
            PlayBank(b, t.Pos, 1f, Mathf.Lerp(1.05f, 0.85f, Mathf.Clamp01((t.Radius - 0.6f) / 2f)));
        }

        /// <summary>Wreck pulled into the car: clunk + reward chime that climbs while pickups keep coming.</summary>
        public void Absorb(Vector3 pos, float vol = 1f)
        {
            if (!banks.TryGetValue("absorb", out var b)) return;
            float now = Time.unscaledTime;
            if (now - absorbCombo > 1.6f) absorbStep = 0;
            else absorbStep = Mathf.Min(absorbStep + 1, b.clips.Length - 1);
            absorbCombo = now;
            b.lastTime = -10f; // chimes may overlap
            PlayBank(b, pos, vol, 1f, absorbStep);
        }

        public void Crash(Vector3 pos, float intensity)
        {
            Play(Kind.Crash, pos, Mathf.Lerp(0.35f, 1f, intensity));
            if (intensity > 0.75f) Play(Kind.Glass, pos, 0.5f);
        }

        /// <summary>Lowers the music for a moment (stingers, boss kill).</summary>
        public void Duck(float seconds, float level = 0.45f)
        {
            duckUntil = Time.unscaledTime + seconds;
            duck = Mathf.Min(duck, level);
        }

        // ------------------------------------------------------------------ continuous layers
        void Update()
        {
            float dt = Time.unscaledDeltaTime;
            var g = Game.I;
            var p = g != null ? g.player : null;
            bool paused = g != null && g.paused;
            bool alive = p != null && p.Alive;
            float speed = p != null ? p.Speed : 0f;
            float speed01 = Mathf.Clamp01(speed / CarTuning.TopSpeed);
            bool asphalt = p != null && p.OnAsphalt;
            float slip = p != null ? Mathf.Max(p.Slide, p.WheelSpin) : 0f;
            float sfxOn = _on && !paused ? 1f : 0f;

            SetLoop(wind, 0.13f * sfxOn, dt, 1.5f);
            SetLoop(rolling, (asphalt ? 0.1f : 0.32f) * speed01 * (alive ? 1f : 0f) * sfxOn, dt, 6f);
            if (rolling != null) rolling.pitch = Mathf.Lerp(0.8f, 1.25f, speed01);
            SetLoop(skidAsphalt, asphalt ? Mathf.Clamp01((slip - 0.2f) * 1.6f) * 0.38f * sfxOn : 0f, dt, 10f);
            SetLoop(skidDirt, !asphalt ? Mathf.Clamp01((slip - 0.15f) * 1.5f) * 0.45f * sfxOn : 0f, dt, 10f);
            if (skidAsphalt != null) skidAsphalt.pitch = Mathf.Lerp(0.9f, 1.1f, speed01);

            // adaptive music: exploration bed + combat layer
            float want = 0f;
            if (g != null && g.Ready && alive)
            {
                if (g.EngagedBoss != null) want = 1f;
                else if (g.world != null && g.world.EnemiesEngaged(p.Pos, 20f) > 0) want = 1f;
            }
            musicIntensity = Mathf.MoveTowards(musicIntensity, want, dt / (want > musicIntensity ? 1.5f : 4f));
            if (Time.unscaledTime > duckUntil) duck = Mathf.MoveTowards(duck, 1f, dt * 0.7f);
            float mv = _musicOn ? 0.62f * duck * (paused ? 0.6f : 1f) : 0f;
            if (musicBase != null) musicBase.volume = Mathf.MoveTowards(musicBase.volume, mv * 0.72f, dt * 0.8f);
            if (musicAction != null) musicAction.volume = Mathf.MoveTowards(musicAction.volume, mv * musicIntensity, dt * 0.8f);
        }

        static void SetLoop(AudioSource a, float target, float dt, float rate)
        {
            if (a == null) return;
            a.volume = Mathf.MoveTowards(a.volume, target, dt * rate * 0.2f + 0.0001f);
            if (a.volume > 0.001f && !a.isPlaying) a.Play();
        }
    }
}
